DO $ddl$ DECLARE r record;d text;t text; BEGIN FOR r IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('maletas_visibilidade','consultora_maletas','remessas_buscar') LOOP d:=pg_get_functiondef(r.oid); FOREACH t IN ARRAY ARRAY['legado_acertos_consultora','legado_maleta_categorias','legado_maleta_vendidos','legado_representantes','legado_acertos_praca','legado_consultoras','legado_maleta_status','legado_remessas','legado_maletas','legado_pracas','legado_notas','consultant_profiles','remessas','kit_cycles','cob_pracas'] LOOP d:=regexp_replace(d,'\m'||t||'\M','colab_v_'||t,'g'); END LOOP; EXECUTE d; END LOOP; END $ddl$;